CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, organisation_id BIGINT UNSIGNED NOT NULL, module_code VARCHAR(64) NOT NULL, title VARCHAR(190) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(organisation_id) REFERENCES organisations(id), INDEX(organisation_id,module_code), CHECK(status IN ('active','locked','archived'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
